{"path": "outline.json", "content": "{
  "title": "每日重置的爱人",
  "structure": "三幕结构（6500字）",
  "act_one": {
    "word_count": "0-1500字",
    "scenes": [
      {
        "scene_id": 1,
        "name": "白色牢笼的清晨",
        "word_count": "0-300字",
        "content": "林浅在白色病房醒来，记忆空白。沈妄推门而入，带着温柔的笑和药瓶。墙上隐约可见刻痕。",
        "y_axis_visual": "纯白病房、铁门、药瓶、墙上淡淡刻痕",
        "hook": "林浅问：今天是几号？沈妄答：是我们相遇的第一天。"
      },
      {
        "scene_id": 2,
        "name": "第一次接触",
        "word_count": "300-800字",
        "content": "沈妄带林浅在院子里散步，讲述他们的爱情故事。林浅被他的温柔吸引，开始产生好感。",
        "x_axis_display": "沈妄的超忆症让他记得所有细节，包括林浅喜欢的花、说话的语气",
        "relationship": "男女主建立初步好感，林浅开始依赖沈妄"
      },
      {
        "scene_id": 3,
        "name": "病历本的秘密",
        "word_count": "800-1200字",
        "content": "林浅发现病历本上的记录从诊断变成了情书。沈妄解释这是他们的爱情记录。",
        "object_transformation": "病历本：诊断工具→情书",
        "tension": "林浅隐约觉得不对劲，但被沈妄的温柔安抚"
      },
      {
        "scene_id": 4,
        "name": "第一次危机",
        "word_count": "1200-1500字",
        "content": "林浅试图离开病房，发现门被锁。沈妄出现，温柔地解释这是为了保护她。林浅选择相信。",
        "conflict": "外部压制：封闭空间的规则",
        "hook": "林浅问：明天你还会来吗？沈妄答：我每天都会重新追求你。"
      }
    ]
  },
  "act_two": {
    "word_count": "1500-5000字",
  "scenes": [
      {
        "scene_id": 5,
        "name": "循环的日常",
        "word_count": "1500-2000字",
        "content": "展示多个循环的片段。沈妄每天重复追求，林浅每天重新爱上他。墙上的刻字越来越多。",
        "x_axis_display": "沈妄的疯狂：墙上刻满'今天她笑了几次'，记录每一个细节",
        "relationship": "依赖关系加深，林浅完全依赖沈妄"
      },
      {
        "scene_id": 6,
        "name": "药瓶的真相",
        "word_count": "2000-2500字",
        "content": "林浅发现药瓶里的药被调换。她开始怀疑，但沈妄用温柔的谎言掩盖。",
        "object_transformation": "药瓶：治疗→控制",
        "tension": "林浅的怀疑与沈妄的控制形成张力"
      },
      {
        "scene_id": 7,
        "name": "墙上的刻字",
        "word_count": "2500-3500字",
        "content": "林浅仔细看墙上的刻字，发现不仅有'今天她笑了几次'，还有日期和详细记录。她意识到时间在流逝。",
        "x_axis_climax": "疯狂的显影：沈妄不仅控制现在，还记录过去，制造虚假的永恒",
        "emotional_peak": "林浅感到恐惧，但也被这种极致的关注震撼"
      },
      {
        "scene_id": 8,
        "name": "觉醒时刻",
        "word_count": "3500-4500字",
        "content": "林浅某天没有失忆。她看到沈妄在墙上刻字，听到他自言自语：'只要她不记得，就永远不会离开'。",
        "revelation": "真相揭露：男主故意让她依赖，实验是为了创造完美爱情",
        "conflict": "认知颠覆：爱情是真实的还是虚构的？"
      },
      {
        "scene_id": 9,
        "name": "对峙",
        "word_count": "4500-5000字",
        "content": "林浅质问沈妄。沈妄坦白一切：他利用超忆症和药物维持她的失忆，因为'只有疯子的爱情才纯粹'。",
        "x_axis_core": "C16疯狂的本质：为了爱而毁灭对方的清醒",
        "tension": "道德困境：离开还是留下？"
      }
    ]
  },
  "act_three": {
    "word_count": "5000-6500字",
    "scenes": [
      {
        "scene_id": 10,
        "name": "选择",
        "word_count": "5000-5500字",
        "content": "林浅有机会逃离，但她看着墙上的刻字，看着沈妄恐惧的眼神。她做出了选择。",
        "choice": "极限二选一：清醒的痛苦vs疯狂的幸福",
        "emotional": "病态的纯粹：她理解了沈妄的疯狂"
      },
      {
        "scene_id": 11,
        "name": "自愿疯狂",
        "word_count": "5500-6000字",
        "content": "林浅选择留下，甚至主动要求继续服药。她说：'那你明天记得再追我一次'。",
        "object_closure": "病历本：囚禁记录；药瓶：每日仪式；墙上刻字：爱的证明",
        "x_axis_resolution": "疯狂的闭环：两人共同选择了疯狂"
      },
      {
        "scene_id": 12,
        "name": "新稳态",
        "word_count": "6000-6500字",
        "content": "第二天清晨，林浅再次醒来，记忆空白。沈妄推门而入，带着温柔的笑。循环继续，但这次是两人共同的选择。",
        "closure": "封蜡结尾：没有解脱，只有永恒的循环",
        "final_image": "墙上新增一行刻字：'她选择了留下'"
      }
