    {
      "name": "药瓶",
      "states": ["治疗", "控制", "每日仪式"],
      "symbolism": "从治愈工具到控制手段再到仪式化的爱情象征"
    },
    {
      "name": "墙上刻字",
      "states": ["今日笑了几次", "详细记录", "爱的证明"],
      "symbolism": "疯狂的具象化，时间的刻度，爱情的墓碑"
    }
  ],
  "theme": "病态的纯粹：当爱情需要通过毁灭清醒来维持，它还是爱情吗？",
  "tension_progression": "外部规则压制→内部怀疑滋生→真相揭露→自愿沉沦"
}"}

